"""Generated by the NL to Flow Diagram Encoder Pipeline."""

matrix = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]

n = len(matrix)

print('Matrix Before Rotation:')

row = 0

loop = True

while loop:
    try:
        print(matrix[row])
        row = (row + 1)
    except Exception:
        loop = False

row = 0

loop = True

while loop:
    col = (row + 1)
    innerloop = True
    while innerloop:
        try:
            temp = matrix[row][col]
            matrix[row][col] = matrix[col][row]
            matrix[col][row] = temp
            col = (col + 1)
        except Exception:
            innerloop = False
    row = (row + 1)
    if (row >= n):
        loop = False

row = 0

loop = True

while loop:
    left = 0
    right = (n - 1)
    innerloop = True
    while innerloop:
        if (left >= right):
            innerloop = False
        else:
            temp = matrix[row][left]
            matrix[row][left] = matrix[row][right]
            matrix[row][right] = temp
            left = (left + 1)
            right = (right - 1)
    row = (row + 1)
    if (row >= n):
        loop = False

print('\nMatrix After 90° Clockwise Rotation:')

row = 0

loop = True

while loop:
    try:
        print(matrix[row])
        row = (row + 1)
    except Exception:
        loop = False
